import React, { useState, useRef } from 'react';
import { ArrowLeftRight, Volume2, Copy, Check, Sparkles, BookPlus, RefreshCw, Upload, FileText, Download, FileCheck, FileType } from 'lucide-react';
import { translateText, detectLanguage, textToSpeech, addVocab, scanDocument, translateDocumentFile } from '../services/api';
import { DEFAULT_SUPPORTED_LANGUAGES } from '../services/languages';

const TranslationTool = ({ languages = DEFAULT_SUPPORTED_LANGUAGES, selectedLang, username }) => {
  const [translationMode, setTranslationMode] = useState('text'); // 'text' or 'doc'
  const [sourceLang, setSourceLang] = useState('auto');
  const [targetLang, setTargetLang] = useState(selectedLang || 'es');

  // Text Mode States
  const [inputText, setInputText] = useState('');
  const [translatedText, setTranslatedText] = useState('');
  const [detectedMeta, setDetectedMeta] = useState(null);
  const [isLoadingText, setIsLoadingText] = useState(false);
  const [isCopied, setIsCopied] = useState(false);
  const [isSavedVocab, setIsSavedVocab] = useState(false);
  const [isPlayingAudio, setIsPlayingAudio] = useState(false);

  // Document Mode States
  const [selectedFile, setSelectedFile] = useState(null);
  const [docScanResult, setDocScanResult] = useState(null);
  const [isScanningDoc, setIsScanningDoc] = useState(false);
  const [isTranslatingDoc, setIsTranslatingDoc] = useState(false);
  const [translatedDocBlob, setTranslatedDocBlob] = useState(null);
  const [downloadFilename, setDownloadFilename] = useState('');

  const fileInputRef = useRef(null);
  const activeLangs = languages && Object.keys(languages).length > 0 ? languages : DEFAULT_SUPPORTED_LANGUAGES;

  // --- Text Mode Handlers ---
  const handleTranslateText = async () => {
    if (!inputText.trim()) return;
    setIsLoadingText(true);
    setIsCopied(false);
    setIsSavedVocab(false);

    try {
      let actualSource = sourceLang;
      if (sourceLang === 'auto') {
        const det = await detectLanguage(inputText);
        setDetectedMeta(det);
        actualSource = det.code;
      } else {
        setDetectedMeta(null);
      }

      const res = await translateText(inputText, targetLang, actualSource === 'auto' ? null : actualSource);
      setTranslatedText(res.translated_text);
    } catch (e) {
      console.error("Translation error:", e);
      setTranslatedText("Translation error. Please check backend server connection.");
    } finally {
      setIsLoadingText(false);
    }
  };

  const handleSwapText = () => {
    if (sourceLang === 'auto') {
      if (detectedMeta) {
        setSourceLang(targetLang);
        setTargetLang(detectedMeta.code);
      } else {
        setSourceLang(targetLang);
        setTargetLang('en');
      }
    } else {
      const temp = sourceLang;
      setSourceLang(targetLang);
      setTargetLang(temp);
    }

    if (translatedText) {
      setInputText(translatedText);
      setTranslatedText(inputText);
    }
  };

  const handleCopyText = () => {
    if (!translatedText) return;
    navigator.clipboard.writeText(translatedText);
    setIsCopied(true);
    setTimeout(() => setIsCopied(false), 2000);
  };

  const handlePlayAudio = async () => {
    if (!translatedText) return;
    setIsPlayingAudio(true);
    try {
      const audioUrl = await textToSpeech(translatedText, targetLang);
      const audio = new Audio(audioUrl);
      audio.onended = () => setIsPlayingAudio(false);
      await audio.play();
    } catch (e) {
      console.error("Audio playback error:", e);
      setIsPlayingAudio(false);
    }
  };

  const handleSaveToVocab = async () => {
    if (!inputText || !translatedText) return;
    try {
      await addVocab(username, translatedText, targetLang, inputText);
      setIsSavedVocab(true);
      setTimeout(() => setIsSavedVocab(false), 2500);
    } catch (e) {
      console.error("Error saving vocabulary:", e);
    }
  };

  // --- Document Mode Handlers ---
  const handleFileSelect = async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setSelectedFile(file);
    setDocScanResult(null);
    setTranslatedDocBlob(null);
    setIsScanningDoc(true);

    try {
      const scanRes = await scanDocument(file);
      setDocScanResult(scanRes);
      if (scanRes.detected_language) {
        setSourceLang(scanRes.detected_language.code);
      }
    } catch (err) {
      console.error("Document scan error:", err);
    } finally {
      setIsScanningDoc(false);
    }
  };

  const handleTranslateDocument = async () => {
    if (!selectedFile) return;
    setIsTranslatingDoc(true);
    try {
      const blob = await translateDocumentFile(selectedFile, targetLang, sourceLang);
      setTranslatedDocBlob(blob);
      const baseName = selectedFile.name.replace(/\.[^/.]+$/, "");
      setDownloadFilename(`${baseName}_translated_${targetLang}.docx`);
    } catch (err) {
      console.error("Document translation error:", err);
    } finally {
      setIsTranslatingDoc(false);
    }
  };

  const handleDownloadDoc = () => {
    if (!translatedDocBlob) return;
    const url = window.URL.createObjectURL(new Blob([translatedDocBlob]));
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', downloadFilename || 'translated_document.docx');
    document.body.appendChild(link);
    link.click();
    link.parentNode.removeChild(link);
  };

  const samplePhrases = [
    "Hello! How are you today?",
    "Where is the nearest restaurant?",
    "Thank you very much for your help.",
    "It is a pleasure to meet you."
  ];

  const sourceMeta = sourceLang === 'auto' 
    ? { name: '✨ Auto Detect Language', flag: '🌐', native: 'Automatic' } 
    : activeLangs[sourceLang] || { name: sourceLang, flag: '🌐', native: '' };

  const targetMeta = activeLangs[targetLang] || { name: 'Spanish', flag: '🇪🇸', native: 'Español' };

  return (
    <div className="glass-panel" style={{ flex: 1, display: 'flex', flexDirection: 'column', padding: '24px', gap: '20px', overflowY: 'auto' }}>
      {/* Top Header & Mode Switcher */}
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', borderBottom: '1px solid rgba(255, 255, 255, 0.1)', paddingBottom: '16px', flexWrap: 'wrap', gap: '10px' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
          <div style={{ background: 'linear-gradient(135deg, #8b5cf6, #ec4899)', padding: '10px', borderRadius: '12px' }}>
            <Sparkles size={20} color="#fff" />
          </div>
          <div>
            <h2 style={{ fontSize: '18px', fontWeight: 700, color: '#fff' }}>Neural Translation Studio</h2>
            <p style={{ fontSize: '12px', color: '#9ca3af' }}>Text & DOCX Document Translation across 51 world languages</p>
          </div>
        </div>

        {/* Translation Type Sub-tabs */}
        <div style={{ display: 'flex', background: 'rgba(255, 255, 255, 0.05)', padding: '4px', borderRadius: '10px', gap: '4px', border: '1px solid rgba(255, 255, 255, 0.1)' }}>
          <button
            onClick={() => setTranslationMode('text')}
            style={{
              padding: '6px 14px',
              borderRadius: '8px',
              border: 'none',
              fontSize: '12px',
              fontWeight: 600,
              cursor: 'pointer',
              background: translationMode === 'text' ? 'linear-gradient(135deg, #3b82f6, #8b5cf6)' : 'transparent',
              color: translationMode === 'text' ? '#fff' : '#9ca3af',
              display: 'flex',
              alignItems: 'center',
              gap: '6px'
            }}
          >
            <FileType size={14} /> Text Mode
          </button>
          <button
            onClick={() => setTranslationMode('doc')}
            style={{
              padding: '6px 14px',
              borderRadius: '8px',
              border: 'none',
              fontSize: '12px',
              fontWeight: 600,
              cursor: 'pointer',
              background: translationMode === 'doc' ? 'linear-gradient(135deg, #ec4899, #8b5cf6)' : 'transparent',
              color: translationMode === 'doc' ? '#fff' : '#9ca3af',
              display: 'flex',
              alignItems: 'center',
              gap: '6px'
            }}
          >
            <FileText size={14} /> DOCX Document Mode
          </button>
        </div>
      </div>

      {/* TEXT TRANSLATION MODE */}
      {translationMode === 'text' && (
        <>
          {/* Language Selectors */}
          <div style={{ display: 'flex', alignItems: 'center', gap: '12px', flexWrap: 'wrap' }}>
            <div style={{ flex: 1, minWidth: '220px' }}>
              <label style={{ fontSize: '11px', color: '#9ca3af', display: 'block', marginBottom: '4px' }}>Source Language</label>
              <select 
                value={sourceLang}
                onChange={(e) => setSourceLang(e.target.value)}
                style={{
                  width: '100%',
                  background: 'rgba(30, 41, 59, 0.95)',
                  border: '1px solid rgba(255, 255, 255, 0.2)',
                  borderRadius: '10px',
                  padding: '10px 14px',
                  color: '#fff',
                  fontSize: '14px',
                  fontWeight: 500,
                  outline: 'none',
                  cursor: 'pointer'
                }}
              >
                <option value="auto">✨ Auto Detect Language</option>
                {Object.entries(activeLangs).map(([code, meta]) => (
                  <option key={code} value={code}>
                    {meta.flag} {meta.name} ({meta.native})
                  </option>
                ))}
              </select>
            </div>

            <button 
              onClick={handleSwapText}
              className="icon-action-btn"
              title="Swap languages"
              style={{ padding: '10px 14px', borderRadius: '10px', marginTop: '16px' }}
            >
              <ArrowLeftRight size={18} />
            </button>

            <div style={{ flex: 1, minWidth: '220px' }}>
              <label style={{ fontSize: '11px', color: '#9ca3af', display: 'block', marginBottom: '4px' }}>Target Language (51 Languages)</label>
              <select 
                value={targetLang}
                onChange={(e) => setTargetLang(e.target.value)}
                style={{
                  width: '100%',
                  background: 'rgba(30, 41, 59, 0.95)',
                  border: '1px solid rgba(255, 255, 255, 0.2)',
                  borderRadius: '10px',
                  padding: '10px 14px',
                  color: '#fff',
                  fontSize: '14px',
                  fontWeight: 500,
                  outline: 'none',
                  cursor: 'pointer'
                }}
              >
                {Object.entries(activeLangs).map(([code, meta]) => (
                  <option key={code} value={code}>
                    {meta.flag} {meta.name} ({meta.native})
                  </option>
                ))}
              </select>
            </div>
          </div>

          {/* Workspace Grid */}
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '16px', flex: 1 }}>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <span style={{ fontSize: '12px', color: '#9ca3af', fontWeight: 500 }}>
                  Input Text ({sourceMeta.name}) {detectedMeta && <span style={{ color: '#c084fc' }}>(Detected: {detectedMeta.name})</span>}
                </span>
                <span style={{ fontSize: '11px', color: '#6b7280' }}>{inputText.length} chars</span>
              </div>

              <textarea 
                placeholder={`Enter text in ${sourceMeta.name}...`}
                value={inputText}
                onChange={(e) => setInputText(e.target.value)}
                style={{
                  flex: 1,
                  minHeight: '180px',
                  background: 'rgba(15, 23, 42, 0.8)',
                  border: '1px solid rgba(255, 255, 255, 0.15)',
                  borderRadius: '12px',
                  padding: '14px',
                  color: '#fff',
                  fontSize: '14px',
                  lineHeight: '1.6',
                  resize: 'none',
                  outline: 'none'
                }}
              />

              <button 
                onClick={handleTranslateText} 
                disabled={isLoadingText || !inputText.trim()}
                className="glow-btn"
                style={{ marginTop: '8px', padding: '12px' }}
              >
                {isLoadingText ? <RefreshCw size={16} className="animate-spin" /> : <Sparkles size={16} />}
                <span>{isLoadingText ? 'Translating...' : `Translate to ${targetMeta.name}`}</span>
              </button>
            </div>

            <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <span style={{ fontSize: '12px', color: '#9ca3af', fontWeight: 500 }}>
                  Target Output ({targetMeta.flag} {targetMeta.name})
                </span>
              </div>

              <div 
                style={{
                  flex: 1,
                  minHeight: '180px',
                  background: 'rgba(30, 41, 59, 0.6)',
                  border: '1px solid rgba(255, 255, 255, 0.12)',
                  borderRadius: '12px',
                  padding: '14px',
                  color: translatedText ? '#fff' : '#9ca3af',
                  fontSize: '15px',
                  lineHeight: '1.6',
                  userSelect: 'text',
                  direction: targetMeta.dir === 'rtl' ? 'rtl' : 'ltr',
                  textAlign: targetMeta.dir === 'rtl' ? 'right' : 'left'
                }}
              >
                {translatedText || "Translation output will appear here..."}
              </div>

              {translatedText && (
                <div style={{ display: 'flex', gap: '8px', marginTop: '8px', flexWrap: 'wrap' }}>
                  <button onClick={handlePlayAudio} className="icon-action-btn">
                    <Volume2 size={15} color={isPlayingAudio ? "#ec4899" : "#9ca3af"} />
                    <span>{isPlayingAudio ? 'Playing...' : 'Pronunciation'}</span>
                  </button>

                  <button onClick={handleCopyText} className="icon-action-btn">
                    {isCopied ? <Check size={15} color="#10b981" /> : <Copy size={15} />}
                    <span>{isCopied ? 'Copied!' : 'Copy Text'}</span>
                  </button>

                  <button onClick={handleSaveToVocab} className="icon-action-btn">
                    {isSavedVocab ? <Check size={15} color="#10b981" /> : <BookPlus size={15} />}
                    <span>{isSavedVocab ? 'Saved to SM-2' : 'Save to Vocab'}</span>
                  </button>
                </div>
              )}
            </div>
          </div>

          {/* Sample Chips */}
          <div style={{ borderTop: '1px solid rgba(255, 255, 255, 0.1)', paddingTop: '14px' }}>
            <div style={{ fontSize: '12px', color: '#9ca3af', marginBottom: '8px' }}>Try common phrases:</div>
            <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap' }}>
              {samplePhrases.map((phrase, i) => (
                <button 
                  key={i}
                  onClick={() => { setInputText(phrase); }}
                  className="icon-action-btn"
                  style={{ fontSize: '12px' }}
                >
                  "{phrase}"
                </button>
              ))}
            </div>
          </div>
        </>
      )}

      {/* DOCUMENT TRANSLATION MODE (.DOCX) */}
      {translationMode === 'doc' && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '20px', flex: 1 }}>
          {/* Target Language Selection for Document */}
          <div style={{ display: 'flex', alignItems: 'center', gap: '16px', flexWrap: 'wrap' }}>
            <div style={{ flex: 1, minWidth: '240px' }}>
              <label style={{ fontSize: '12px', color: '#9ca3af', display: 'block', marginBottom: '6px', fontWeight: 500 }}>
                Select Target Document Translation Language (51 Languages):
              </label>
              <select 
                value={targetLang}
                onChange={(e) => setTargetLang(e.target.value)}
                style={{
                  width: '100%',
                  background: 'rgba(30, 41, 59, 0.95)',
                  border: '1px solid rgba(255, 255, 255, 0.2)',
                  borderRadius: '10px',
                  padding: '10px 14px',
                  color: '#fff',
                  fontSize: '14px',
                  fontWeight: 600,
                  outline: 'none',
                  cursor: 'pointer'
                }}
              >
                {Object.entries(activeLangs).map(([code, meta]) => (
                  <option key={code} value={code}>
                    {meta.flag} {meta.name} ({meta.native})
                  </option>
                ))}
              </select>
            </div>
          </div>

          {/* Upload Drop Zone */}
          <div 
            onClick={() => fileInputRef.current?.click()}
            style={{
              border: '2px dashed rgba(139, 92, 246, 0.4)',
              borderRadius: '16px',
              padding: '36px 20px',
              textAlign: 'center',
              background: 'rgba(139, 92, 246, 0.05)',
              cursor: 'pointer',
              transition: 'all 0.2s ease',
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'center',
              gap: '12px'
            }}
            onMouseEnter={(e) => {
              e.currentTarget.style.borderColor = '#c084fc';
              e.currentTarget.style.background = 'rgba(139, 92, 246, 0.1)';
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.borderColor = 'rgba(139, 92, 246, 0.4)';
              e.currentTarget.style.background = 'rgba(139, 92, 246, 0.05)';
            }}
          >
            <input 
              ref={fileInputRef}
              type="file" 
              accept=".docx,.txt"
              onChange={handleFileSelect}
              style={{ display: 'none' }}
            />
            <div style={{ background: 'linear-gradient(135deg, #ec4899, #8b5cf6)', width: '56px', height: '56px', borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', boxShadow: '0 6px 20px rgba(236, 72, 153, 0.3)' }}>
              <Upload size={26} color="#fff" />
            </div>
            <div>
              <h3 style={{ fontSize: '16px', fontWeight: 600, color: '#fff', marginBottom: '4px' }}>
                {selectedFile ? selectedFile.name : "Click or Drag & Drop Microsoft Word (.docx) File Here"}
              </h3>
              <p style={{ fontSize: '12px', color: '#9ca3af' }}>
                Supports Microsoft Word (.docx) & Plain Text (.txt) files. Auto scans language and paragraph structure.
              </p>
            </div>
          </div>

          {/* Document Scan Result & Detection Card */}
          {isScanningDoc && (
            <div style={{ display: 'flex', alignItems: 'center', gap: '10px', padding: '16px', background: 'rgba(255, 255, 255, 0.05)', borderRadius: '12px', color: '#fff' }}>
              <RefreshCw size={18} className="animate-spin" color="#c084fc" />
              <span>Scanning document structure and detecting language across 51 languages...</span>
            </div>
          )}

          {docScanResult && (
            <div className="glass-panel" style={{ padding: '20px', display: 'flex', flexDirection: 'column', gap: '14px', background: 'rgba(30, 41, 59, 0.7)' }}>
              <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', flexWrap: 'wrap', gap: '10px' }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
                  <FileCheck size={22} color="#10b981" />
                  <div>
                    <h4 style={{ fontSize: '15px', fontWeight: 600, color: '#fff' }}>{docScanResult.filename}</h4>
                    <p style={{ fontSize: '11px', color: '#9ca3af' }}>
                      {docScanResult.word_count} words • {docScanResult.paragraph_count} paragraphs
                    </p>
                  </div>
                </div>

                {/* Auto Detected Language Badge */}
                {docScanResult.detected_language && (
                  <div style={{ background: 'rgba(16, 185, 129, 0.2)', border: '1px solid rgba(16, 185, 129, 0.4)', borderRadius: '12px', padding: '6px 14px', display: 'flex', alignItems: 'center', gap: '8px' }}>
                    <span style={{ fontSize: '18px' }}>{docScanResult.detected_language.flag || '🌐'}</span>
                    <div>
                      <div style={{ fontSize: '11px', color: '#9ca3af' }}>Auto Detected Language:</div>
                      <div style={{ fontSize: '13px', fontWeight: 700, color: '#34d399' }}>
                        {docScanResult.detected_language.name} ({docScanResult.detected_language.native})
                      </div>
                    </div>
                  </div>
                )}
              </div>

              {/* Document Sample Preview */}
              <div style={{ background: 'rgba(15, 23, 42, 0.8)', padding: '12px 16px', borderRadius: '10px', fontSize: '13px', color: '#cbd5e1', fontStyle: 'italic', border: '1px dashed rgba(255, 255, 255, 0.15)' }}>
                <strong>Document Sample Preview:</strong> "{docScanResult.sample_text}"
              </div>

              {/* Translate & Download Buttons */}
              <div style={{ display: 'flex', gap: '12px', flexWrap: 'wrap', marginTop: '6px' }}>
                <button 
                  onClick={handleTranslateDocument}
                  disabled={isTranslatingDoc}
                  className="glow-btn"
                  style={{ flex: 1, padding: '12px 20px', minWidth: '220px' }}
                >
                  {isTranslatingDoc ? <RefreshCw size={16} className="animate-spin" /> : <Sparkles size={16} />}
                  <span>{isTranslatingDoc ? 'Translating Document Paragraphs...' : `Translate Entire Document into ${targetMeta.name}`}</span>
                </button>

                {translatedDocBlob && (
                  <button 
                    onClick={handleDownloadDoc}
                    style={{
                      background: 'linear-gradient(135deg, #10b981, #059669)',
                      color: '#fff',
                      border: 'none',
                      borderRadius: '12px',
                      padding: '12px 24px',
                      fontSize: '14px',
                      fontWeight: 700,
                      cursor: 'pointer',
                      display: 'inline-flex',
                      alignItems: 'center',
                      gap: '8px',
                      boxShadow: '0 4px 14px rgba(16, 185, 129, 0.4)'
                    }}
                  >
                    <Download size={18} />
                    <span>Download Translated DOCX File</span>
                  </button>
                )}
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default TranslationTool;
